using System.Net.Http;using System.Text.Json;using Serilog;namespace QuanLyDatTour.Services;public class TyGiaSettings{public string PrimaryUrl{get;set;}="";public string FallbackUrl{get;set;}="";public int TimeoutSeconds{get;set;}=8;public int CacheMinutes{get;set;}=10;}public class TyGiaService{static readonly HttpClient http=new();readonly TyGiaSettings cfg;readonly Dictionary<string,(decimal rate,DateTime time,string url)> cache=new(StringComparer.OrdinalIgnoreCase);public TyGiaService(TyGiaSettings s){cfg=s;http.Timeout=TimeSpan.FromSeconds(Math.Max(1,s.TimeoutSeconds));}public async Task<decimal> LayTyGiaAsync(string ngoaiTe){string code=ngoaiTe.ToLowerInvariant();if(code=="vnd")return 1;if(cache.TryGetValue(code,out var old)&&DateTime.Now-old.time<TimeSpan.FromMinutes(cfg.CacheMinutes))return old.rate;string primary=cfg.PrimaryUrl.Replace("{code}",code),fallback=cfg.FallbackUrl.Replace("{code}",code);try{var rate=await Read(primary,code);cache[code]=(rate,DateTime.Now,primary);Log.Information("Exchange rate {Code} fetched from primary URL",code);return rate;}catch(Exception ex){Log.Warning(ex,"Primary exchange-rate URL failed for {Code}; trying fallback",code);try{var rate=await Read(fallback,code);cache[code]=(rate,DateTime.Now,fallback);Log.Information("Exchange rate {Code} fetched from fallback URL",code);return rate;}catch(Exception ex2){Log.Error(ex2,"Both exchange-rate URLs failed for {Code}",code);throw new InvalidOperationException("Không thể lấy tỷ giá từ cả hai địa chỉ API.",ex2);}}}static async Task<decimal> Read(string url,string code){using var response=await http.GetAsync(url);response.EnsureSuccessStatusCode();using var doc=JsonDocument.Parse(await response.Content.ReadAsStringAsync());return doc.RootElement.GetProperty(code).GetProperty("vnd").GetDecimal();}}